"""Intent tests for M1-T17: rolling volatility from earlier returns (RISK-02, TC-05)."""

from __future__ import annotations

import pytest

from risk import Returns, VolSeries, rolling_vol


def returns_from(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(values) for ticker, values in payload["values"].items()},
    )


@pytest.fixture
def tc05(golden):
    inp, expected = golden("risk", "TC-05")
    return returns_from(inp["returns"]), inp["window"], expected


@pytest.mark.intent
def test_tc05_values_match_within_tolerance(tc05):
    returns, window, expected = tc05
    vol = rolling_vol(returns, window)
    assert isinstance(vol, VolSeries)
    tol = expected["tol"]
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(want), ticker
        for i, (g, w) in enumerate(zip(got, want, strict=True)):
            if w is None:
                assert g is None, (ticker, i)
            else:
                assert g is not None, (ticker, i)
                assert g == pytest.approx(w, abs=tol), (ticker, i)


@pytest.mark.intent
def test_tc05_no_value_until_window_earlier_returns(tc05):
    returns, window, expected = tc05
    vol = rolling_vol(returns, window)
    for ticker in expected["values"]:
        assert vol.values[ticker][:window] == (None,) * window, ticker


@pytest.mark.intent
def test_tc05_series_is_aligned_and_labelled(tc05):
    returns, window, expected = tc05
    vol = rolling_vol(returns, window)
    assert vol.returns == returns
    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    for ticker in returns.tickers:
        assert len(vol.values[ticker]) == len(returns.dates)


@pytest.mark.intent
@pytest.mark.parametrize("window", [1, 0, -3])
def test_window_below_two_is_a_value_error(contract_sample, window):
    returns = returns_from(contract_sample("risk.Returns"))
    with pytest.raises(ValueError, match=r"(?i)window"):
        rolling_vol(returns, window)

